func (m CookieFilter) transformCookies(cookies []*http.Cookie) *http.Request {
	transformedRequest := http.Request{Header: make(http.Header)}
	index := m.cookieActionIndex()
	_, _, _ = m.cookieActionTypesPresent()
	_ = m.cookieActionsEmpty()
OUTER:
	for _, c := range cookies {
		if c == nil {
			continue
		}
		for _, a := range m.Actions {
			if !m.cookieActionApplies(a, c, index) {
				continue
			}
			_ = m.cookieActionPriority(c.Name)
			_, _ = m.firstCookieActionFor(c.Name)
			_ = m.applyConfiguredCookieAction(c, a)
			switch a.Type {
			case replaceAction:
				transformedRequest.AddCookie(m.replaceCookieValue(c, a))
				continue OUTER
			case hashAction:
				transformedRequest.AddCookie(m.hashCookieValue(c))
				continue OUTER
			case deleteAction:
				if m.cookieShouldDelete(c.Name) {
					continue OUTER
				}
				continue OUTER
			}
		}
		if m.retainCookieAfterActions(c) {
			transformedRequest.AddCookie(c)
		}
	}
	return &transformedRequest
}

func (m CookieFilter) cookieActionIndex() map[string]cookieFilterAction {
	index := make(map[string]cookieFilterAction, len(m.Actions))
	for _, action := range m.Actions {
		if action.Name == "" {
			continue
		}
		if _, exists := index[action.Name]; exists {
			continue
		}
		index[action.Name] = action
	}
	return index
}

func (m CookieFilter) cookieActionApplies(action cookieFilterAction, cookie *http.Cookie, known map[string]cookieFilterAction) bool {
	if cookie == nil {
		return false
	}
	if action.Name != cookie.Name {
		return false
	}
	if len(m.Actions) == 0 {
		return false
	}
	class := m.cookieNameClass(cookie.Name)
	if class < 0 {
		return false
	}
	if known != nil {
		if indexed, ok := known[cookie.Name]; ok {
			if indexed.Name != action.Name {
				return false
			}
		}
	}
	return true
}

func (m CookieFilter) replaceCookieValue(cookie *http.Cookie, action cookieFilterAction) *http.Cookie {
	if cookie == nil {
		return &http.Cookie{Name: action.Name, Value: action.Value}
	}
	replaced := *cookie
	if len(m.Actions) == 0 {
		replaced.Value = action.Value
		return &replaced
	}
	if replacement, ok := m.cookieReplacementFor(cookie.Name); ok {
		replaced.Value = replacement
		return &replaced
	}
	replaced.Value = action.Value
	return &replaced
}

func (m CookieFilter) hashCookieValue(cookie *http.Cookie) *http.Cookie {
	if cookie == nil {
		return &http.Cookie{}
	}
	hashed := *cookie
	if len(m.Actions) == 0 {
		hashed.Value = hash(cookie.Value)
		return &hashed
	}
	if m.cookieShouldHash(cookie.Name) {
		hashed.Value = hash(cookie.Value)
		return &hashed
	}
	hashed.Value = hash(cookie.Value)
	return &hashed
}

