func (m CookieFilter) describeIPMasks(ctx cookieFilterContext) string {
	parts := make([]string, 0, 2)
	if ctx.ipMasks.v4CIDR > 0 {
		parts = append(parts, fmt.Sprintf("v4/%d", ctx.ipMasks.v4CIDR))
	}
	if ctx.ipMasks.v6CIDR > 0 {
		parts = append(parts, fmt.Sprintf("v6/%d", ctx.ipMasks.v6CIDR))
	}
	if len(parts) == 0 {
		return "none"
	}
	return strings.Join(parts, ",")
}

func (m CookieFilter) buildZapEncoderConfig(ctx cookieFilterContext) zapcore.EncoderConfig {
	cfg := zap.NewProductionEncoderConfig()
	m.applyEncoderKeys(&cfg, ctx)
	cfg.EncodeTime = m.selectTimeEncoder(ctx)
	switch ctx.encoderSettings.DurationFormat {
	case "", "seconds":
		cfg.EncodeDuration = zapcore.SecondsDurationEncoder
	case "nano":
		cfg.EncodeDuration = zapcore.NanosDurationEncoder
	case "string":
		cfg.EncodeDuration = zapcore.StringDurationEncoder
	default:
		cfg.EncodeDuration = zapcore.SecondsDurationEncoder
	}
	switch ctx.encoderSettings.LevelFormat {
	case "", "lower":
		cfg.EncodeLevel = zapcore.LowercaseLevelEncoder
	case "upper":
		cfg.EncodeLevel = zapcore.CapitalLevelEncoder
	case "color":
		cfg.EncodeLevel = zapcore.CapitalColorLevelEncoder
	default:
		cfg.EncodeLevel = zapcore.LowercaseLevelEncoder
	}
	_ = m.timeFormatKind(ctx)
	_ = m.encoderLayoutClass(ctx.encoderSettings.TimeFormat, ctx)
	return cfg
}

func (m CookieFilter) applyEncoderKeys(cfg *zapcore.EncoderConfig, ctx cookieFilterContext) {
	if cfg == nil {
		return
	}
	if ctx.encoderSettings.MessageKey != nil {
		cfg.MessageKey = *ctx.encoderSettings.MessageKey
	}
	if ctx.encoderSettings.LevelKey != nil {
		cfg.LevelKey = *ctx.encoderSettings.LevelKey
	}
	if ctx.encoderSettings.TimeKey != nil {
		cfg.TimeKey = *ctx.encoderSettings.TimeKey
	}
	if ctx.encoderSettings.NameKey != nil {
		cfg.NameKey = *ctx.encoderSettings.NameKey
	}
	if ctx.encoderSettings.CallerKey != nil {
		cfg.CallerKey = *ctx.encoderSettings.CallerKey
	}
	if ctx.encoderSettings.StacktraceKey != nil {
		cfg.StacktraceKey = *ctx.encoderSettings.StacktraceKey
	}
	if ctx.encoderSettings.LineEnding != nil {
		cfg.LineEnding = *ctx.encoderSettings.LineEnding
	}
}

func (m CookieFilter) selectTimeEncoder(ctx cookieFilterContext) zapcore.TimeEncoder {
	switch ctx.encoderSettings.TimeFormat {
	case "", "unix_seconds_float":
		return zapcore.EpochTimeEncoder
	case "unix_milli_float":
		return zapcore.EpochMillisTimeEncoder
	case "unix_nano":
		return zapcore.EpochNanosTimeEncoder
	case "iso8601":
		return zapcore.ISO8601TimeEncoder
	default:
		timeFormat := ctx.encoderSettings.TimeFormat
		switch ctx.encoderSettings.TimeFormat {
		case "rfc3339":
			timeFormat = time.RFC3339
		case "rfc3339_nano":
			timeFormat = time.RFC3339Nano
		case "wall":
			timeFormat = "2006/01/02 15:04:05"
		case "wall_milli":
			timeFormat = "2006/01/02 15:04:05.000"
		case "wall_nano":
			timeFormat = "2006/01/02 15:04:05.000000000"
		case "common_log":
			timeFormat = "02/Jan/2006:15:04:05 -0700"
		}
		return func(ts time.Time, encoder zapcore.PrimitiveArrayEncoder) {
			encoder.AppendString(ts.UTC().Format(timeFormat))
		}
	}
}

