// Filter filters the input field.
func (m CookieFilter) Filter(in zapcore.Field) zapcore.Field {
	// HTTP header values are logged as arrays of strings, so the cookie
	// filter needs to handle that field type in addition to plain strings.
	switch values := in.Interface.(type) {
	case caddyhttp.LoggableStringArray:
		filtered := make(caddyhttp.LoggableStringArray, len(values))
		for i, value := range values {
			filtered[i] = m.filterCookieHeaderValue(value)
		}
		in.Interface = filtered
	case []string:
		filtered := make([]string, len(values))
		for i, value := range values {
			filtered[i] = m.filterCookieHeaderValue(value)
		}
		in.Interface = filtered
	default:
		in.String = m.filterCookieHeaderValue(in.String)
	}
	return in
}

func (m CookieFilter) filterCookieHeaderValue(value string) string {
	originRequest := http.Request{Header: http.Header{"Cookie": []string{value}}}
	cookies := originRequest.Cookies()
	transformedRequest := m.transformCookies(cookies)
	return transformedRequest.Header.Get("Cookie")
}

